"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

_IDENTIFIER = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
    r"(?:\+(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
)

# Longest operators first so ``>=`` is not read as ``>`` followed by ``=``.
_OPERATORS = (">=", "<=", "=", ">", "<", "^", "~")


def _is_numeric(identifier: str) -> bool:
    return identifier.isdigit()


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    major, minor, patch, prerelease, build = match.groups()
    prerelease_ids = tuple(prerelease.split(".")) if prerelease else ()
    for identifier in prerelease_ids:
        if _is_numeric(identifier) and len(identifier) > 1 and identifier[0] == "0":
            raise ValueError(f"invalid version: {text!r}")
    build_ids = tuple(build.split(".")) if build else ()

    return Version(int(major), int(minor), int(patch), prerelease_ids, build_ids)


def _as_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    return parse(value)


def _compare_prerelease(
    left: tuple[str, ...], right: tuple[str, ...]
) -> int:
    if not left and not right:
        return 0
    if not left:
        return 1
    if not right:
        return -1

    for a, b in zip(left, right):
        if a == b:
            continue
        a_numeric = _is_numeric(a)
        b_numeric = _is_numeric(b)
        if a_numeric and b_numeric:
            return -1 if int(a) < int(b) else 1
        if a_numeric:
            return -1
        if b_numeric:
            return 1
        return -1 if a < b else 1

    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _as_version(a)
    right = _as_version(b)

    for field in ("major", "minor", "patch"):
        x = getattr(left, field)
        y = getattr(right, field)
        if x != y:
            return -1 if x < y else 1

    return _compare_prerelease(left.prerelease, right.prerelease)


# A comparator is (operator, version). Caret and tilde comparators are
# expanded into a pair of >= and < comparators when a range is parsed.
_Comparator = tuple[str, Version]


def _parse_comparator(text: str) -> list[_Comparator]:
    operator = "="
    for candidate in _OPERATORS:
        if text.startswith(candidate):
            operator = candidate
            text = text[len(candidate):]
            break

    version = parse(text)

    if operator == "^":
        if version.major:
            upper = Version(version.major + 1, 0, 0)
        elif version.minor:
            upper = Version(0, version.minor + 1, 0)
        else:
            upper = Version(0, 0, version.patch + 1)
        return [(">=", version), ("<", upper)]

    if operator == "~":
        upper = Version(version.major, version.minor + 1, 0)
        return [(">=", version), ("<", upper)]

    return [(operator, version)]


def _parse_range(range_: str) -> list[list[_Comparator]]:
    sets: list[list[_Comparator]] = []
    for chunk in range_.split("||"):
        parts = chunk.split()
        if not parts:
            raise ValueError(f"invalid range: {range_!r}")
        comparators: list[_Comparator] = []
        for part in parts:
            comparators.extend(_parse_comparator(part))
        sets.append(comparators)
    return sets


def _test(version: Version, operator: str, target: Version) -> bool:
    result = compare(version, target)
    if operator == "=":
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    return result <= 0


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _as_version(version)

    for comparators in _parse_range(range_):
        if candidate.prerelease:
            same_core = any(
                comparator.prerelease
                and (comparator.major, comparator.minor, comparator.patch)
                == (candidate.major, candidate.minor, candidate.patch)
                for _, comparator in comparators
            )
            if not same_core:
                continue

        if all(_test(candidate, operator, target) for operator, target in comparators):
            return True

    return False

"""Randomized property checks for devkit.semver."""

import itertools
import random
import sys

sys.path.insert(0, "/private/tmp/tmptl2cxfzr/pete/projects/devkit")

from devkit.semver import Version, compare, parse, satisfies  # noqa: E402

rng = random.Random(20261027)

letters = "abcXYZ-"
chars = "0123456789" + letters


def rand_identifier(numeric_ok=True):
    if numeric_ok and rng.random() < 0.45:
        return str(rng.randrange(0, 30))
    length = rng.randrange(1, 5)
    ident = "".join(rng.choice(chars) for _ in range(length))
    if ident.isdigit():
        ident += "a"
    return ident


def rand_version():
    major = rng.randrange(0, 4)
    minor = rng.randrange(0, 4)
    patch = rng.randrange(0, 4)
    pre = tuple(rand_identifier() for _ in range(rng.randrange(0, 4)))
    build = tuple(rand_identifier() for _ in range(rng.randrange(0, 3)))
    return Version(major, minor, patch, pre, build)


def stripped(v):
    return (v.major, v.minor, v.patch, v.prerelease)


versions = [rand_version() for _ in range(400)]

failures = []

for v in versions:
    text = str(v)
    reparsed = parse(text)
    if reparsed != v:
        failures.append(f"roundtrip {v!r} -> {text!r} -> {reparsed!r}")
    if str(reparsed) != text:
        failures.append(f"canonical unstable for {text!r}")

for a, b in itertools.combinations(versions, 2):
    ab = compare(a, b)
    ba = compare(b, a)
    if ab not in (-1, 0, 1):
        failures.append(f"compare out of range: {a} {b} -> {ab}")
    if ab != -ba:
        failures.append(f"antisymmetry: {a} vs {b}: {ab}, {ba}")
    if (ab == 0) != (stripped(a) == stripped(b)):
        failures.append(f"zero mismatch: {a} vs {b}: {ab}")

for a, b, c in itertools.islice(itertools.combinations(versions, 3), 0, 4000):
    if compare(a, b) <= 0 and compare(b, c) <= 0:
        if compare(a, c) > 0:
            failures.append(f"transitivity: {a} <= {b} <= {c} but not {a} <= {c}")

# Build metadata must never change any outcome.
for v in versions[:100]:
    with_build = Version(v.major, v.minor, v.patch, v.prerelease, ("zzz", "1"))
    if compare(v, with_build) != 0:
        failures.append(f"build affected compare: {v} vs {with_build}")
    if satisfies(v, f">={v}") != satisfies(with_build, f">={v}"):
        failures.append(f"build affected satisfies: {v}")

# Caret/tilde boundaries against explicitly computed bounds.
def caret_upper(v):
    if v.major:
        return Version(v.major + 1, 0, 0)
    if v.minor:
        return Version(0, v.minor + 1, 0)
    return Version(0, 0, v.patch + 1)


for _ in range(500):
    v = rand_version()
    upper = caret_upper(v)
    lower_ok = Version(v.major, v.minor, v.patch, v.prerelease)
    if not satisfies(lower_ok, f"^{v}"):
        failures.append(f"caret lower bound: {v}")
    if satisfies(str(upper), f"^{v}"):
        failures.append(f"caret upper bound: {v} < {upper}")
    tilde_upper = Version(v.major, v.minor + 1, 0)
    if not satisfies(lower_ok, f"~{v}"):
        failures.append(f"tilde lower bound: {v}")
    if satisfies(str(tilde_upper), f"~{v}"):
        failures.append(f"tilde upper bound: {v} < {tilde_upper}")

print(f"{len(versions)} versions, {len(failures)} failure(s)")
for failure in failures[:20]:
    print("FAIL:", failure)
sys.exit(1 if failures else 0)
